 disconnectedCallback(){window.YankeAppearance?.releaseViewport(this);window.removeEventListener('yanke-appearance-ready',this._appearance);document.removeEventListener('visibilitychange',this._visibility);this.motion?.removeEventListener('change',this._motion);clearInterval(this.historyTimer);clearTimeout(this.feedbackTimer);this.disposeScene();}
 state(key){return this._hass?.states?.[E[key]];}
